CREATE OR REPLACE FUNCTION public.activate_vip(p_plan_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); v_cost integer; v_duration interval; v_tier text; v_balance integer; v_current_vip_until timestamp with time zone; v_new_vip_until timestamp with time zone; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; CASE p_plan_code WHEN 'essencial' THEN v_cost := 300; v_duration := interval '7 days'; v_tier := 'essencial'; WHEN 'mensal' THEN v_cost := 900; v_duration := interval '30 days'; v_tier := 'mensal'; WHEN 'premium' THEN v_cost := 2200; v_duration := interval '90 days'; v_tier := 'premium'; ELSE RAISE EXCEPTION 'Plano VIP inválido'; END CASE; INSERT INTO public.credit_wallets (user_id) VALUES (v_user_id) ON CONFLICT (user_id) DO NOTHING; SELECT balance, vip_until INTO v_balance, v_current_vip_until FROM public.credit_wallets WHERE user_id = v_user_id FOR UPDATE; IF v_balance < v_cost THEN RAISE EXCEPTION 'Créditos insuficientes para este plano VIP'; END IF; v_new_vip_until := GREATEST(COALESCE(v_current_vip_until, now()), now()) + v_duration; INSERT INTO public.credit_transactions (user_id, amount, transaction_type, description, metadata) VALUES (v_user_id, -v_cost, 'vip_purchase', 'Ativação do VIP ' || v_tier, jsonb_build_object('plan_code', p_plan_code, 'duration_days', extract(day from v_duration), 'cost', v_cost)); UPDATE public.credit_wallets SET balance = balance - v_cost, lifetime_spent = lifetime_spent + v_cost, vip_tier = v_tier, vip_until = v_new_vip_until, updated_at = now() WHERE user_id = v_user_id RETURNING balance INTO v_balance; RETURN jsonb_build_object('plan_code', p_plan_code, 'cost', v_cost, 'balance', v_balance, 'vip_tier', v_tier, 'vip_until', v_new_vip_until); END; $$;